PLACES = {}
DIVISIONS = []
BN_NAMES = {}
# fields = ["name", "name_bn", "type", "parent", "children"]


def doit(lst):
    todo = []
    for id, name, name_bn, parent_id, type in lst:
        if parent_id is None:
            assert type == "division"
            p = Place(name, name_bn, type, None, [])
            PLACES[id] = p
            DIVISIONS.append(p)
        elif (parent := PLACES.get(parent_id, None)) is not None:
            p = Place(name, name_bn, type, parent, [])
            PLACES[id] = p
            parent.children.append(p)
        else:
            todo.append((id, name, name_bn, parent_id, type))
            continue
        BN_NAMES[name] = name_bn
    return todo


todo = doit(unresolved_places)
while len(todo) > 0:
    todo = doit(todo)

PLACES = list(PLACES.values())
